-- Module 26: performance indexes for hot paths (idempotent)
SET @exists := (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND index_name = 'idx_posts_author_cursor');
SET @sql := IF(@exists = 0, 'CREATE INDEX idx_posts_author_cursor ON posts (author_id, id DESC)', 'SELECT 1');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
